CREATE DATABASE IF NOT EXISTS easy_bike_rentals_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE easy_bike_rentals_db;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(40),address VARCHAR(500),role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS customers(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bike_categories(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE,description VARCHAR(300));
CREATE TABLE IF NOT EXISTS bikes(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,brand VARCHAR(100),model VARCHAR(100),category VARCHAR(60),fuel_type VARCHAR(40),engine_cc INT,price_per_hour DECIMAL(10,2) NOT NULL,price_per_day DECIMAL(10,2) NOT NULL,security_deposit DECIMAL(10,2) DEFAULT 0,description VARCHAR(1000),image_url VARCHAR(1000),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS bookings(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(30) NOT NULL UNIQUE,customer_id BIGINT NOT NULL,bike_id BIGINT NOT NULL,pickup_at DATETIME NOT NULL,return_at DATETIME NOT NULL,pickup_location VARCHAR(200),return_location VARCHAR(200),license_number VARCHAR(100),status VARCHAR(30) NOT NULL DEFAULT 'PENDING',total_amount DECIMAL(10,2) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_booking_user FOREIGN KEY(customer_id) REFERENCES users(id),CONSTRAINT fk_booking_bike FOREIGN KEY(bike_id) REFERENCES bikes(id),INDEX idx_bike_period(bike_id,pickup_at,return_at,status));
CREATE TABLE IF NOT EXISTS payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL,amount DECIMAL(10,2) NOT NULL,method ENUM('CASH','UPI','CARD') NOT NULL,status ENUM('PENDING','TEST_PAID','REFUNDED','FAILED') NOT NULL DEFAULT 'PENDING',transaction_reference VARCHAR(100),paid_at DATETIME,CONSTRAINT fk_payment_booking FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS contact_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL,phone VARCHAR(40),subject VARCHAR(200) NOT NULL,message VARCHAR(4000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id BIGINT AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,bike_id BIGINT NOT NULL,rating TINYINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(bike_id) REFERENCES bikes(id));
CREATE TABLE IF NOT EXISTS rental_locations(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,address VARCHAR(300) NOT NULL,city VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
